function metricVal(insightsObj, name) {
  const arr = insightsObj?.data || [];
  const m = arr.find(x => x.name === name);
  if (!m || !m.values || !m.values.length) return 0;
  const v = m.values[0].value;
  return typeof v === 'object' ? Object.values(v).reduce((a,b)=>a+b,0) : (v||0);
}

